window.docContents[205].resolve({"/2___-Basic-notions-of-representation-theory/2___11___-Tensor-products/Tensor-product-over-a-ring/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___11___-Tensor-products--Tensor-product-over-a-ring":{"contents":"\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.11. Tensor products","header":"Tensor product over a ring","id":"/2___-Basic-notions-of-representation-theory/2___11___-Tensor-products/Tensor-product-over-a-ring/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___11___-Tensor-products--Tensor-product-over-a-ring"},"/2___-Basic-notions-of-representation-theory/2___3___-Representations/1-dimensional-representations-are-automatically-irreducible/#Chapter2___Remark2___3___13___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.3. Representations\u00091-dimensional representations are automatically irreducible\u00091-dimensional representations are automatically irreducible","header":"Formalization","id":"/2___-Basic-notions-of-representation-theory/2___3___-Representations/1-dimensional-representations-are-automatically-irreducible/#Chapter2___Remark2___3___13___formalization"},"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Ado___s-theorem/#Chapter2___Remark2___9___3":{"contents":"Remark 2.9.3. Ado's theorem says that any finite dimensional Lie algebra is a Lie subalgebra of \\mathfrak{gl}(V) for a suitable finite dimensional vector space V.\n\n\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.9. Lie algebras\u0009Ado's theorem","header":"Ado's theorem","id":"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Ado___s-theorem/#Chapter2___Remark2___9___3"},"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Universal-enveloping-algebra/#Chapter2___Definition2___9___9":{"contents":"Definition 2.9.9. Let \\mathfrak{g} be a Lie algebra with basis x_i and [\\ ,\\ ] defined by [x_i, x_j] = \\sum_k c^k_{ij} x_k. The universal enveloping algebra U(\\mathfrak{g}) is the associative algebra generated by the x_i's with the defining relations x_i x_j - x_j x_i = \\sum_k c^k_{ij} x_k.\n\n\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.9. Lie algebras\u0009Universal enveloping algebra","header":"Universal enveloping algebra","id":"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Universal-enveloping-algebra/#Chapter2___Definition2___9___9"},"/5___-Representations-of-finite-groups___-Further-results/5___15___-The-Frobenius-character-formula/Equivalent-formulation-of-Theorem-5___15___1-using-Laurent-polynomials/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___15___-The-Frobenius-character-formula--Equivalent-formulation-of-Theorem-5___15___1-using-Laurent-polynomials":{"contents":"\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.15. The Frobenius character formula","header":"Equivalent formulation of Theorem 5.15.1 using Laurent polynomials","id":"/5___-Representations-of-finite-groups___-Further-results/5___15___-The-Frobenius-character-formula/Equivalent-formulation-of-Theorem-5___15___1-using-Laurent-polynomials/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___15___-The-Frobenius-character-formula--Equivalent-formulation-of-Theorem-5___15___1-using-Laurent-polynomials"},"/5___-Representations-of-finite-groups___-Further-results/5___4___-Burnside___s-theorem/Solvable-group/#Chapter5___Definition5___4___1":{"contents":"Definition 5.4.1. A group G is called solvable if there exists a series of nested normal subgroups\n\n\\{e\\} = G_1 \\lhd G_2 \\lhd \\ldots \\lhd G_n = G\n\nwhere G_{i+1}/G_i is abelian for all 1 \\leq i \\leq n - 1.\n\n\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.4. Burnside's theorem\u0009Solvable group","header":"Solvable group","id":"/5___-Representations-of-finite-groups___-Further-results/5___4___-Burnside___s-theorem/Solvable-group/#Chapter5___Definition5___4___1"},"/5___-Representations-of-finite-groups___-Further-results/5___5___-Historical-interlude___-William-Burnside-and-intellectual-harmony-in-mathematics/Section-5___5___-Historical-interlude-___-William-Burnside/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___5___-Historical-interlude___-William-Burnside-and-intellectual-harmony-in-mathematics--Section-5___5___-Historical-interlude-___-William-Burnside":{"contents":"\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.5. Historical interlude: William Burnside and intellectual harmony in mathematics","header":"Section 5.5: Historical interlude — William Burnside","id":"/5___-Representations-of-finite-groups___-Further-results/5___5___-Historical-interlude___-William-Burnside-and-intellectual-harmony-in-mathematics/Section-5___5___-Historical-interlude-___-William-Burnside/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___5___-Historical-interlude___-William-Burnside-and-intellectual-harmony-in-mathematics--Section-5___5___-Historical-interlude-___-William-Burnside"},"/7___-Introduction-to-categories/7___2___-Functors/Composition-of-functors-and-identity-functor/#Chapter7___Discussion_after_Definition7___2___1___formalization":{"contents":"\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.2. Functors\u0009Composition of functors and identity functor\u0009Composition of functors and identity functor","header":"Formalization","id":"/7___-Introduction-to-categories/7___2___-Functors/Composition-of-functors-and-identity-functor/#Chapter7___Discussion_after_Definition7___2___1___formalization"},"/7___-Introduction-to-categories/7___6___-Adjoint-functors/Ubiquity-of-adjoint-functors/#Chapter7___Discussion_after_Example7___6___3":{"contents":"One can give many more examples, spanning many fields. These examples show that adjoint functors are ubiquitous in mathematics.\n\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.6. Adjoint functors\u0009Ubiquity of adjoint functors","header":"Ubiquity of adjoint functors","id":"/7___-Introduction-to-categories/7___6___-Adjoint-functors/Ubiquity-of-adjoint-functors/#Chapter7___Discussion_after_Example7___6___3"},"/7___-Introduction-to-categories/7___7___-Abelian-categories/Abelian-category/#Chapter7___Definition7___7___1":{"contents":"Definition 7.7.1. An abelian category is a category (enriched over the category of abelian groups) which is equivalent to a full subcategory \\mathcal{C} of the category A-mod of left modules over a ring A, closed under taking finite direct sums, as well as kernels, cokernels, and images of morphisms.\n\n\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.7. Abelian categories\u0009Abelian category","header":"Abelian category","id":"/7___-Introduction-to-categories/7___7___-Abelian-categories/Abelian-category/#Chapter7___Definition7___7___1"},"/Frontmatter/#frontmatter":{"contents":"\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory","header":"Frontmatter","id":"/Frontmatter/#frontmatter"}});